```typescript
/**
 * 在已升序排序的数组中二分查找 target。
 * @returns target 的索引；不存在时返回 -1。
 * 若存在重复元素，返回其中任意一个的下标。
 */
function binarySearch(arr: readonly number[], target: number): number {
  let left = 0;
  let right = arr.length - 1;

  while (left <= right) {
    // 等价于 (left + right) / 2 向下取整，写成减法可避免大数相加溢出
    const mid = left + ((right - left) >> 1);

    if (arr[mid] === target) {
      return mid;
    }
    if (arr[mid] < target) {
      left = mid + 1;
    } else {
      right = mid - 1;
    }
  }

  return -1;
}
```

使用示例：

```typescript
binarySearch([1, 3, 5, 7, 9], 7);  // 2
binarySearch([1, 3, 5, 7, 9], 4);  // -1
```

几点说明：

- 时间复杂度 O(log n)，空间 O(1)。
- 参数用 `readonly number[]`，传入普通 `number[]` 或 `as const` 数组都可以。
- 有重复元素时返回的下标不固定。如果你需要「第一个匹配」或「最后一个匹配」，把命中分支改成继续收缩边界即可，例如第一个匹配：`arr[mid] === target` 时记录 `result = mid; right = mid - 1;`。
- 注意 `>> 1` 对超过 2^31-1 的下标会出错（数组实际不可能有这么大，安全），追求严格可用 `Math.floor((left + right) / 2)`。
